create function private.competency_utf16_length(value text) returns integer
language sql immutable strict parallel safe set search_path = '' as $$
  select coalesce(sum(case when pg_catalog.ascii(c) > 65535 then 2 else 1 end), 0)::integer
  from pg_catalog.unnest(pg_catalog.string_to_array(value, null)) c;
$$;
revoke all on function private.competency_utf16_length(text) from public;

create function private.competency_visible_count(value text) returns integer
language plpgsql immutable parallel safe set search_path = '' as $$
declare
  chars text[]; points integer[] := '{}'; flags integer[] := '{}';
  total integer; i integer := 1; j integer; k integer; script integer;
  visible integer := 0; meaningful integer := 0; current_flags integer;
  before_flags integer; after_flags integer; previous_emoji integer;
  accepted boolean; same_mark boolean; letter_bit integer; mark_bit integer;
  viramas constant integer[] := array[2381,2509,2637,2765,2893,3021,3149,3277,3405,3530];
begin
  if value is null then return -1; end if;
  chars := pg_catalog.string_to_array(value, null);
  total := coalesce(pg_catalog.array_length(chars, 1), 0);
  -- One classification per code point, reused by all contextual checks.
  for j in 1..total loop
    points := pg_catalog.array_append(points, pg_catalog.ascii(chars[j]));
    flags := pg_catalog.array_append(flags, private.competency_unicode_flags(points[j]));
  end loop;
  while i <= total loop
    current_flags := flags[i];
    -- The three RGI subdivision flags in Unicode 17.0: gbeng, gbsct, gbwls.
    if points[i] = 127988 and (
      points[i:i+6] = array[127988,917607,917602,917605,917614,917607,917631]
      or points[i:i+6] = array[127988,917607,917602,917619,917603,917620,917631]
      or points[i:i+6] = array[127988,917607,917602,917623,917612,917619,917631]
    ) then visible := visible + 1; meaningful := meaningful + 1; i := i + 7; continue; end if;
    if points[i] in (9,10,13) then i := i + 1; continue; end if;
    if (current_flags & 64) <> 0 then return -1; end if;
    if (current_flags & 4) <> 0 then
      before_flags := coalesce(flags[i-1], 0); after_flags := coalesce(flags[i+1], 0);
      accepted := false;
      if points[i] in (65038,65039) then
        accepted := (before_flags & 8) <> 0 or (points[i] = 65039
          and (points[i-1] between 48 and 57 or points[i-1] in (35,42)) and points[i+1] = 8419);
      end if;
      if points[i] between 917760 and 917999 and (before_flags & 512) <> 0 then accepted := true; end if;
      previous_emoji := i - 1;
      while previous_emoji >= 1 and ((flags[previous_emoji] & 32) <> 0 or points[previous_emoji] in (65038,65039)) loop
        previous_emoji := previous_emoji - 1;
      end loop;
      if points[i] = 8205 and previous_emoji >= 1 and (flags[previous_emoji] & 8) <> 0 and (after_flags & 8) <> 0 then accepted := true; end if;
      if points[i] = 173 and (before_flags & 16) <> 0 and (after_flags & 16) <> 0 then accepted := true; end if;
      if points[i] = 8204 and (before_flags & 128) <> 0 and (after_flags & 128) <> 0 then accepted := true; end if;
      -- UAX #31 Indic context, identical to indicConjunctJoiner in SC-014-A.
      if points[i] in (8204,8205) then
        j := i - 1;
        while j >= 1 and (flags[j] & 256) <> 0 and not (points[j] = any(viramas)) loop j := j - 1; end loop;
        script := case when j >= 1 then pg_catalog.array_position(viramas, points[j]) else null end;
        if script is not null then
          letter_bit := 1 << (10 + script); mark_bit := 1 << (20 + script); same_mark := true;
          for k in reverse i-1..j+1 loop
            if (flags[k] & 256) = 0 or ((flags[k] & mark_bit) = 0 and (flags[k] & 1024) = 0) then same_mark := false; exit; end if;
          end loop;
          j := j - 1;
          while j >= 1 and (flags[j] & 256) <> 0 and ((flags[j] & mark_bit) <> 0 or (flags[j] & 1024) <> 0) loop j := j - 1; end loop;
          if same_mark and j >= 1 and (flags[j] & letter_bit) <> 0 then
            if points[i] = 8205 then
              if (after_flags & mark_bit) = 0 then accepted := true; end if;
            else
              j := i + 1;
              while j <= total and (flags[j] & 256) <> 0 and ((flags[j] & mark_bit) <> 0 or (flags[j] & 1024) <> 0) loop j := j + 1; end loop;
              if j <= total and (flags[j] & letter_bit) <> 0 then accepted := true; end if;
            end if;
          end if;
        end if;
      end if;
      if not coalesce(accepted, false) then return -1; end if;
      i := i + 1; continue;
    end if;
    if points[i] <> 10240 then
      if (current_flags & 1) <> 0 then visible := visible + 1; end if;
      if (current_flags & 2) <> 0 then meaningful := meaningful + 1; end if;
    end if;
    i := i + 1;
  end loop;
  return case when meaningful > 0 then visible else -1 end;
end;
$$;
revoke all on function private.competency_visible_count(text) from public;

create function private.competency_answer(payload jsonb) returns text
language plpgsql immutable parallel safe set search_path = '' as $$
declare answer text;
begin
  if pg_catalog.jsonb_typeof(payload) is distinct from 'object'
    or pg_catalog.jsonb_typeof(payload->'workSample') is distinct from 'string' then
    raise exception 'Invalid competency answer' using errcode = 'PT422';
  end if;
  answer := payload->>'workSample';
  -- PostgreSQL UTF8 length counts code points. Bound RAW input before trim.
  if pg_catalog.length(answer) > 20000 then
    raise exception 'Answer exceeds 20000 code points' using errcode = 'PT422';
  end if;
  if private.competency_visible_count(answer) < 1 or private.competency_trim(answer) = '' then
    raise exception 'Answer requires visible content' using errcode = 'PT422';
  end if;
  return private.competency_trim(answer);
end;
$$;
revoke all on function private.competency_answer(jsonb) from public;

create function private.competency_validate_definition(definition jsonb) returns jsonb
language plpgsql immutable set search_path = '' as $$
declare canonical jsonb; criterion jsonb; field text; maximum integer;
begin
  -- SC-008 validates shape, kind, duration, criteria, canonical text, duplicate
  -- competencies and distinct anchors. SC-014-A additionally bounds all raw
  -- text in UTF-16 units; enforce that BEFORE issue, start and human review.
  canonical := private.validate_exercise_definition(definition);
  if canonical->>'kind' <> 'competency_test' then raise exception 'Not a competency test' using errcode = 'PT422'; end if;
  foreach field in array array['title','instructions','expectedOutput'] loop
    maximum := case field when 'title' then 200 when 'instructions' then 10000 else 4000 end;
    if private.competency_utf16_length(definition->>field) > maximum then raise exception 'Invalid rubric text length' using errcode = 'PT422'; end if;
  end loop;
  for criterion in select value from pg_catalog.jsonb_array_elements(definition->'criteria') loop
    foreach field in array array['competency','below','meets','above'] loop
      maximum := case field when 'competency' then 200 else 2000 end;
      if private.competency_utf16_length(criterion->>field) > maximum then raise exception 'Invalid rubric text length' using errcode = 'PT422'; end if;
    end loop;
  end loop;
  return canonical;
end;
$$;
revoke all on function private.competency_validate_definition(jsonb) from public;

create function private.competency_score(definition jsonb, answer text, observations jsonb) returns jsonb
language plpgsql immutable set search_path = '' as $$
declare
  canonical jsonb; row jsonb; results jsonb := '[]';
  total integer; i integer; known integer := 0; points integer := 0;
  quote text; rating text; coverage numeric;
begin
  canonical := private.competency_validate_definition(definition);
  answer := private.competency_answer(pg_catalog.jsonb_build_object('workSample', answer));
  total := pg_catalog.jsonb_array_length(canonical->'criteria');
  if pg_catalog.jsonb_typeof(observations) is distinct from 'array' then raise exception 'Invalid observations' using errcode = 'PT422'; end if;
  if pg_catalog.jsonb_array_length(observations) <> total then raise exception 'One observation per criterion required' using errcode = 'PT422'; end if;
  for i in 0..total-1 loop
    row := observations->i;
    if pg_catalog.jsonb_typeof(row) is distinct from 'object'
      or pg_catalog.jsonb_typeof(row->'criterionIndex') is distinct from 'number'
      or (row->>'criterionIndex')::numeric <> i
      or pg_catalog.jsonb_typeof(row->'rating') is distinct from 'string'
      or (row->>'rating') not in ('below','meets','above','insufficient_data')
      or pg_catalog.jsonb_typeof(row->'evidence') is distinct from 'string' then
      raise exception 'Invalid criterion index, rating or evidence' using errcode = 'PT422';
    end if;
    if pg_catalog.length(row->>'evidence') > 10000 then raise exception 'Evidence exceeds 10000 UTF16 units' using errcode = 'PT422'; end if;
    if private.competency_utf16_length(row->>'evidence') > 10000 then raise exception 'Evidence exceeds 10000 UTF16 units' using errcode = 'PT422'; end if;
    quote := private.competency_trim(row->>'evidence'); rating := row->>'rating';
    if rating = 'insufficient_data' then
      if quote <> '' then raise exception 'Insufficient data cannot include evidence' using errcode = 'PT422'; end if;
    else
      if private.competency_visible_count(quote) < 3 or pg_catalog.strpos(answer, quote) = 0 then
        raise exception 'Exact visible evidence required' using errcode = 'PT422';
      end if;
      known := known + 1;
      points := points + case rating when 'below' then 0 when 'meets' then 50 else 100 end;
    end if;
    results := results || pg_catalog.jsonb_build_array(pg_catalog.jsonb_build_object('criterionIndex', i,
      'rating', rating, 'evidence', quote, 'competency', canonical->'criteria'->i->>'competency'));
  end loop;
  coverage := known::numeric / total;
  return pg_catalog.jsonb_build_object('policyVersion', 'competency-test-rubric-v1',
    'criterionResults', results, 'totalCriteria', total, 'evidencedCriteria', known,
    'coverage', pg_catalog.round(coverage, 4),
    'score', case when coverage >= 0.6 and known > 0 then pg_catalog.round(points::numeric / known, 2) else null end,
    'status', case when coverage >= 0.6 then 'review_required' else 'insufficient_evidence' end);
end;
$$;
revoke all on function private.competency_score(jsonb,text,jsonb) from public;
-- Remove explicit hostile default grants as well as PUBLIC EXECUTE. These
-- helpers remain private even when this file is loaded without the B2 RPC file.
do $$declare r record; g record; begin
  for r in select p.oid,p.proowner from pg_catalog.pg_proc p
    join pg_catalog.pg_namespace n on n.oid=p.pronamespace
    where n.nspname='private' and p.proname in ('competency_unicode_flags',
      'competency_trim','competency_utf16_length','competency_visible_count',
      'competency_answer','competency_validate_definition','competency_score') loop
    for g in select distinct x.grantee,role.rolname from pg_catalog.pg_proc p
      cross join lateral pg_catalog.aclexplode(coalesce(p.proacl,pg_catalog.acldefault('f',p.proowner))) x
      left join pg_catalog.pg_roles role on role.oid=x.grantee
      where p.oid=r.oid and x.grantee<>r.proowner loop
      if g.grantee=0 then execute pg_catalog.format('revoke all on function %s from public',r.oid::pg_catalog.regprocedure);
      else execute pg_catalog.format('revoke all on function %s from %I',r.oid::pg_catalog.regprocedure,g.rolname); end if;
    end loop;
  end loop;
end;$$;


-- Active competency capability protocol.

do $$begin
 if not exists(select 1 from pg_roles where rolname='competency_test_gateway') then
  create role competency_test_gateway nologin nosuperuser nocreatedb nocreaterole noinherit nobypassrls;end if;
 if not exists(select 1 from pg_roles where rolname='competency_test_marker_writer') then
  create role competency_test_marker_writer nologin nosuperuser nocreatedb nocreaterole noinherit nobypassrls;end if;
 if exists(select 1 from pg_roles where rolname in ('competency_test_gateway','competency_test_marker_writer')
  and (rolsuper or rolcreatedb or rolcreaterole or rolbypassrls or rolinherit or rolcanlogin or rolreplication))
  or exists(select 1 from pg_auth_members m join pg_roles r on r.oid=m.roleid or r.oid=m.member
   where r.rolname in ('competency_test_gateway','competency_test_marker_writer') and not (current_user='postgres' and current_setting('server_version_num')::integer/10000 in (16,17)
 and m.roleid=r.oid and exists(select 1 from pg_roles where oid=m.member and rolname='postgres'
 and not rolsuper and rolinherit and rolcreaterole and rolcreatedb and rolcanlogin and rolreplication and rolbypassrls)
 and exists(select 1 from pg_roles where oid=m.grantor and rolname='supabase_admin' and oid=10
 and rolsuper and rolinherit and rolcreaterole and rolcreatedb and rolcanlogin and rolreplication and rolbypassrls)
 and m.admin_option and not m.inherit_option and not m.set_option)) then
  raise exception 'Unsafe existing competency role';end if;
end;$$;
grant usage on schema private to competency_test_gateway,competency_test_marker_writer;
alter table public.candidates add column competency_access_cancelled_at timestamptz,
 add column competency_access_cancel_reason text check(competency_access_cancel_reason in ('consent_withdrawn','candidate_withdrawn')),
 add constraint competency_candidate_marker_pair check((competency_access_cancelled_at is null)=(competency_access_cancel_reason is null));
alter table public.applications add column competency_access_cancelled_at timestamptz,
 add column competency_access_cancel_reason text check(competency_access_cancel_reason in ('consent_withdrawn','candidate_withdrawn')),
 add constraint competency_application_marker_pair check((competency_access_cancelled_at is null)=(competency_access_cancel_reason is null)),
 add constraint competency_application_pair unique(company_id,id),
 add constraint competency_application_binding unique(company_id,recruitment_id,candidate_id,id);
create table private.competency_test_grants (
 id uuid primary key default gen_random_uuid(),company_id uuid not null,candidate_id uuid not null,
 recruitment_id uuid not null,application_id uuid not null,definition_entry_id uuid not null,
 token_digest bytea not null unique check(octet_length(token_digest)=32),revision bigint not null default 1 check(revision>0),
 start_by_at timestamptz not null,created_by uuid not null,created_at timestamptz not null default clock_timestamp(),
 revoked_by uuid,revoked_at timestamptz,issuance_request_key uuid not null,event_request_key uuid not null,
 unique(company_id,application_id,definition_entry_id),unique(company_id,created_by,issuance_request_key),
 unique(company_id,candidate_id,recruitment_id,application_id,definition_entry_id,id),
 foreign key(company_id,recruitment_id,candidate_id,application_id) references public.applications(company_id,recruitment_id,candidate_id,id),
 foreign key(company_id,recruitment_id,definition_entry_id) references public.exercise_definition_entries(company_id,recruitment_id,id),
 check((revoked_by is null)=(revoked_at is null))
);
create table private.competency_test_grant_events (
 id uuid primary key default gen_random_uuid(),company_id uuid not null,candidate_id uuid not null,
 recruitment_id uuid not null,application_id uuid not null,definition_entry_id uuid not null,grant_id uuid not null,
 kind text not null check(kind in ('issued','rotated','revoked')),actor_id uuid not null,
 previous_revision bigint not null,revision bigint not null,token_digest bytea not null check(octet_length(token_digest)=32),
 request_key uuid not null,created_at timestamptz not null default clock_timestamp(),
 unique(company_id,actor_id,kind,request_key),
 foreign key(company_id,candidate_id,recruitment_id,application_id,definition_entry_id,grant_id)
 references private.competency_test_grants(company_id,candidate_id,recruitment_id,application_id,definition_entry_id,id)
);
create table public.competency_test_attempts (
 id uuid primary key default gen_random_uuid(),company_id uuid not null,candidate_id uuid not null,
 recruitment_id uuid not null,application_id uuid not null,definition_entry_id uuid not null,grant_id uuid not null unique,
 state text not null default 'in_progress' check(state in ('in_progress','submitted')),
 started_at timestamptz not null,deadline_at timestamptz not null,submitted_at timestamptz,
 work_sample text,submission_digest bytea,start_request_key uuid not null,
 unique(company_id,candidate_id,recruitment_id,application_id,definition_entry_id,id),
 foreign key(company_id,candidate_id,recruitment_id,application_id,definition_entry_id,grant_id)
 references private.competency_test_grants(company_id,candidate_id,recruitment_id,application_id,definition_entry_id,id),
 check(deadline_at>started_at),
 check((state='in_progress' and submitted_at is null and work_sample is null and submission_digest is null)
 or(state='submitted' and submitted_at is not null and work_sample is not null and submission_digest is not null
 and octet_length(submission_digest)=32 and submitted_at<deadline_at
 and work_sample=private.competency_answer(jsonb_build_object('workSample',work_sample))))
);
create table private.competency_test_sessions (
 id uuid primary key default gen_random_uuid(),company_id uuid not null,candidate_id uuid not null,
 recruitment_id uuid not null,application_id uuid not null,definition_entry_id uuid not null,grant_id uuid not null,
 session_digest bytea not null unique check(octet_length(session_digest)=32),grant_revision bigint not null,
 created_at timestamptz not null default clock_timestamp(),absolute_expires_at timestamptz not null,
 idle_expires_at timestamptz not null,invalidated_at timestamptz,
 unique(grant_id,grant_revision),
 foreign key(company_id,candidate_id,recruitment_id,application_id,definition_entry_id,grant_id)
 references private.competency_test_grants(company_id,candidate_id,recruitment_id,application_id,definition_entry_id,id)
);
create table private.competency_test_drafts (
 id uuid primary key default gen_random_uuid(),company_id uuid not null,candidate_id uuid not null,
 recruitment_id uuid not null,application_id uuid not null,definition_entry_id uuid not null,attempt_id uuid not null unique,
 draft_text text not null check(length(draft_text)<=20000),version bigint not null check(version>0),request_key uuid not null,
 foreign key(company_id,candidate_id,recruitment_id,application_id,definition_entry_id,attempt_id)
 references public.competency_test_attempts(company_id,candidate_id,recruitment_id,application_id,definition_entry_id,id)
);
create table public.competency_test_review_entries (
 id uuid primary key default gen_random_uuid(),company_id uuid not null,candidate_id uuid not null,
 recruitment_id uuid not null,application_id uuid not null,definition_entry_id uuid not null,attempt_id uuid not null,
 reviewer_id uuid not null,version bigint not null check(version>0),submission_digest bytea not null,
 policy_version text not null check(policy_version='competency-test-rubric-v1'),observations jsonb not null,
 coverage numeric not null check(coverage between 0 and 1),score numeric check(score between 0 and 100),
 status text not null check(status in ('review_required','insufficient_evidence')),created_at timestamptz not null default clock_timestamp(),
 unique(attempt_id,version),
 foreign key(company_id,candidate_id,recruitment_id,application_id,definition_entry_id,attempt_id)
 references public.competency_test_attempts(company_id,candidate_id,recruitment_id,application_id,definition_entry_id,id)
);
-- Candidate arrays are explicit SC-010 edges, never guessed from UUID strings.
create table private.competency_test_cancellations (
 id uuid primary key default gen_random_uuid(),company_id uuid not null references public.companies(id),
 candidate_ids uuid[] not null check(cardinality(candidate_ids) between 1 and 100),application_id uuid,
 scope_kind text not null check(scope_kind in ('application','confirmed_subject','resolution_link','historical_withdrawn')),
 resolution_id uuid,resolution_revision bigint,reason text not null check(reason in ('consent_withdrawn','candidate_withdrawn')),
 actor_id uuid not null,request_key uuid not null,created_at timestamptz not null default clock_timestamp(),
 unique(company_id,actor_id,request_key),
 foreign key(company_id,application_id) references public.applications(company_id,id)
);
-- Application lacks this pair in older baselines; the composite binding above
-- already establishes the stricter tenant/recruitment/candidate relationship.

create function private.competency_authority(tenant uuid,owner_only boolean default false) returns void
language plpgsql security definer set search_path='' as $$
begin
 if auth.uid() is null then raise exception using errcode='PT404',message='Resource unavailable';end if;
 perform 1 from public.companies where id=tenant for share nowait;
 if not found then raise exception using errcode='PT404',message='Resource unavailable';end if;
 if exists(select 1 from public.companies where id=tenant and owner_id=auth.uid()) then return;end if;
 if owner_only then raise exception using errcode='PT404',message='Resource unavailable';end if;
 perform 1 from public.company_members where company_id=tenant and user_id=auth.uid() for share nowait;
 if not found or not exists(select 1 from public.company_members where company_id=tenant and user_id=auth.uid() and role='recruiter') then
  raise exception using errcode='PT404',message='Resource unavailable';end if;
exception when lock_not_available then raise exception using errcode='PT409',message='Authority busy';end;$$;

create function private.competency_lock_application(target uuid,staff boolean default false,allow_cancelled boolean default false)
returns public.applications language plpgsql security definer set search_path='' as $$
declare a public.applications;seed public.applications;c public.candidates;
begin
 select * into seed from public.applications where id=target;
 perform private.erasure_lock_candidate(seed.candidate_id);
 -- Serialize restore activation with every B2 operation until COMMIT.
 perform 1 from private.erasure_execution_config where singleton for share nowait;
 if exists(select 1 from private.erasure_execution_config where singleton and restore_isolated) then
  raise exception using errcode='PT409',message='Restore isolation required';end if;
 select * into a from public.applications where id=target for update nowait;
 if a.id is null or row(a.company_id,a.candidate_id,a.recruitment_id) is distinct from row(seed.company_id,seed.candidate_id,seed.recruitment_id) then
  raise exception using errcode='PT409',message='Application changed';end if;
 if staff then perform private.competency_authority(a.company_id);end if;
 select * into c from public.candidates where id=a.candidate_id and company_id=a.company_id;
 if c.id is null or (not allow_cancelled and (c.competency_access_cancelled_at is not null
  or a.competency_access_cancelled_at is not null or a.status='withdrawn')) then
  raise exception using errcode='PT404',message='Resource unavailable';end if;
 return a;
exception when lock_not_available then raise exception using errcode='PT409',message='Application busy';end;$$;

create function private.competency_eligible(a public.applications,definition_id uuid) returns public.exercise_definition_entries
language plpgsql security definer set search_path='' as $$
declare d public.exercise_definition_entries;r public.recruitments;p public.positions;
begin
 select * into r from public.recruitments where company_id=a.company_id and id=a.recruitment_id for share nowait;
 select * into p from public.positions where company_id=a.company_id and id=r.position_id for share nowait;
 select * into d from public.exercise_definition_entries where company_id=a.company_id and recruitment_id=a.recruitment_id and id=definition_id;
 if a.status not in ('new','in_progress') or r.id is null or r.status not in ('draft','open') or p.id is null or p.status='archived'
  or d.id is null or d.definition->>'kind'<>'competency_test' then raise exception using errcode='PT404',message='Resource unavailable';end if;

 -- R1 is enforced on issue, rotation and EVERY capability use, including replay.
 -- A shared row lock serializes removal against capability work until COMMIT.
 perform 1 from public.recruitment_shortlist_entries e
 where e.company_id=a.company_id and e.recruitment_id=a.recruitment_id and e.application_id=a.id
 and e.removed_at is null for share nowait;
 if not found then raise exception using errcode='PT404',message='Resource unavailable';end if;
 perform private.competency_validate_definition(d.definition);
 return d;
exception when lock_not_available then raise exception using errcode='PT409',message='Workflow busy';end;$$;

create function private.competency_grant_audit() returns trigger language plpgsql security definer set search_path='' as $$
declare event_kind text;before_revision bigint;
begin
 if auth.uid() is null then raise exception using errcode='PT404',message='Actor required';end if;
 if tg_op='INSERT' then event_kind:='issued';before_revision:=0;
 else
  if (to_jsonb(new)-array['token_digest','revision','revoked_by','revoked_at','event_request_key']) is distinct from
   (to_jsonb(old)-array['token_digest','revision','revoked_by','revoked_at','event_request_key']) or old.revoked_at is not null then
   raise exception using errcode='42501',message='Grant identity immutable';end if;
  before_revision:=old.revision;
  if new.revoked_at is not null and new.revoked_by=auth.uid() and new.revision=old.revision and new.token_digest=old.token_digest then event_kind:='revoked';
  elsif new.revoked_at is null and new.revision=old.revision+1 and new.token_digest<>old.token_digest then event_kind:='rotated';
  else raise exception using errcode='42501',message='Invalid grant transition';end if;
 end if;
 insert into private.competency_test_grant_events(company_id,candidate_id,recruitment_id,application_id,definition_entry_id,grant_id,
 kind,actor_id,previous_revision,revision,token_digest,request_key)
 values(new.company_id,new.candidate_id,new.recruitment_id,new.application_id,new.definition_entry_id,new.id,event_kind,
 auth.uid(),before_revision,new.revision,new.token_digest,new.event_request_key);
 return new;
end;$$;
create trigger zz_competency_grant_audit after insert or update on private.competency_test_grants for each row execute function private.competency_grant_audit();

create function public.create_competency_test_grant(target_application uuid,target_definition uuid,start_by timestamptz,request_key uuid)
returns jsonb language plpgsql security definer set search_path='' as $$
declare a public.applications;d public.exercise_definition_entries;g private.competency_test_grants;secret text;
begin
 a:=private.competency_lock_application(target_application,true);
 d:=private.competency_eligible(a,target_definition);
 if request_key is null or start_by is null then raise exception using errcode='PT422',message='Invalid grant';end if;
 select * into g from private.competency_test_grants where company_id=a.company_id and created_by=auth.uid() and issuance_request_key=request_key;
 if found then
  if g.application_id<>a.id or g.definition_entry_id<>target_definition or g.start_by_at<>start_by then raise exception using errcode='PT409',message='Request key reused';end if;
  return jsonb_build_object('grantId',g.id,'revision',g.revision,'state','secret_unavailable_rotate_required');end if;
 d:=private.competency_eligible(a,target_definition);
 if start_by<=clock_timestamp() or start_by>clock_timestamp()+interval '7 days' then raise exception using errcode='PT422',message='Invalid start window';end if;
 secret:=encode(extensions.gen_random_bytes(32),'hex');
 insert into private.competency_test_grants(company_id,candidate_id,recruitment_id,application_id,definition_entry_id,token_digest,
 start_by_at,created_by,issuance_request_key,event_request_key) values(a.company_id,a.candidate_id,a.recruitment_id,a.id,d.id,
 extensions.digest(secret,'sha256'),start_by,auth.uid(),request_key,request_key) returning * into g;
 return jsonb_build_object('grantId',g.id,'revision',g.revision,'token',secret);
exception when unique_violation then raise exception using errcode='PT409',message='Grant already exists';end;$$;

create function private.competency_staff_grant(target uuid,allow_cancelled boolean default false) returns private.competency_test_grants
language plpgsql security definer set search_path='' as $$
declare g private.competency_test_grants;a public.applications;
begin
 select * into g from private.competency_test_grants where id=target;
 a:=private.competency_lock_application(g.application_id,true,allow_cancelled);
 select * into g from private.competency_test_grants where id=target and company_id=a.company_id and candidate_id=a.candidate_id for update nowait;
 if not found then raise exception using errcode='PT404',message='Resource unavailable';end if;return g;
exception when lock_not_available then raise exception using errcode='PT409',message='Grant busy';end;$$;
create function public.get_competency_test_grant_status(target uuid) returns jsonb
language plpgsql security definer set search_path='' as $$declare g private.competency_test_grants;begin
 g:=private.competency_staff_grant(target);return jsonb_build_object('grantId',g.id,'revision',g.revision,'revoked',g.revoked_at is not null,'startBy',g.start_by_at);end;$$;
create function public.rotate_competency_test_grant(target uuid,expected_revision bigint,request_key uuid) returns jsonb
language plpgsql security definer set search_path='' as $$
declare g private.competency_test_grants;e private.competency_test_grant_events;secret text;a public.competency_test_attempts;
begin
 g:=private.competency_staff_grant(target);
 perform private.competency_eligible((select app from public.applications app where app.id=g.application_id),g.definition_entry_id);
 if request_key is null or expected_revision is null then raise exception using errcode='PT422',message='Invalid rotation';end if;
 select * into e from private.competency_test_grant_events where company_id=g.company_id and actor_id=auth.uid() and kind='rotated' and competency_test_grant_events.request_key=rotate_competency_test_grant.request_key;
 if found then
  if e.grant_id<>g.id or e.previous_revision<>expected_revision then raise exception using errcode='PT409',message='Request key reused';end if;
  return jsonb_build_object('grantId',g.id,'revision',g.revision,'state','secret_unavailable_rotate_required');end if;
 if g.revoked_at is not null or g.revision<>expected_revision then raise exception using errcode='PT409',message='Grant changed';end if;
 select * into a from public.competency_test_attempts where grant_id=g.id;
 if (a.id is null and g.start_by_at<=clock_timestamp()) or (a.id is not null and a.deadline_at+interval '15 minutes'<=clock_timestamp()) then
  raise exception using errcode='PT404',message='Resource unavailable';end if;
 secret:=encode(extensions.gen_random_bytes(32),'hex');
 update private.competency_test_grants set token_digest=extensions.digest(secret,'sha256'),revision=revision+1,event_request_key=request_key where id=g.id returning * into g;
 update private.competency_test_sessions set invalidated_at=clock_timestamp() where grant_id=g.id and invalidated_at is null;
 return jsonb_build_object('grantId',g.id,'revision',g.revision,'token',secret);
end;$$;
create function public.revoke_competency_test_grant(target uuid,request_key uuid) returns jsonb
language plpgsql security definer set search_path='' as $$declare g private.competency_test_grants;begin
 g:=private.competency_staff_grant(target,true);
 if request_key is null then raise exception using errcode='PT422',message='Invalid revocation';end if;
 if g.revoked_at is null then
  update private.competency_test_grants set revoked_at=clock_timestamp(),revoked_by=auth.uid(),event_request_key=request_key where id=g.id;
  update private.competency_test_sessions set invalidated_at=clock_timestamp() where grant_id=g.id and invalidated_at is null;
 end if;return jsonb_build_object('grantId',g.id,'revoked',true);
end;$$;

-- The gateway only knows a capability, never an auth.uid or company authority.
create function private.exchange_candidate_competency_test_session(token text) returns jsonb
language plpgsql security definer set search_path='' as $$
declare g private.competency_test_grants;a public.applications;attempt public.competency_test_attempts;secret text;expiry timestamptz;
begin
 if token is null or token !~ '^[0-9a-f]{64}$' then raise exception using errcode='PT404',message='Resource unavailable';end if;
 select * into g from private.competency_test_grants where token_digest=extensions.digest(token,'sha256');
 a:=private.competency_lock_application(g.application_id);
 perform private.competency_eligible(a,g.definition_entry_id);
 select * into g from private.competency_test_grants where id=g.id for update nowait;
 if g.token_digest<>extensions.digest(token,'sha256') or g.revoked_at is not null then raise exception using errcode='PT404',message='Resource unavailable';end if;
 select * into attempt from public.competency_test_attempts where grant_id=g.id;
 expiry:=case when attempt.id is null then g.start_by_at else attempt.deadline_at+interval '15 minutes' end;
 if clock_timestamp()>=expiry then raise exception using errcode='PT404',message='Resource unavailable';end if;
 secret:=encode(extensions.gen_random_bytes(32),'hex');
 insert into private.competency_test_sessions(company_id,candidate_id,recruitment_id,application_id,definition_entry_id,grant_id,session_digest,grant_revision,absolute_expires_at,idle_expires_at)
 values(g.company_id,g.candidate_id,g.recruitment_id,g.application_id,g.definition_entry_id,g.id,extensions.digest(secret,'sha256'),g.revision,expiry,expiry);
 return jsonb_build_object('session',secret,'expiresAt',expiry);
exception when unique_violation then raise exception using errcode='PT404',message='Resource unavailable';
 when lock_not_available then raise exception using errcode='PT409',message='Resource busy';end;$$;

create function private.competency_session(session_hash bytea) returns private.competency_test_grants
language plpgsql security definer set search_path='' as $$
declare g private.competency_test_grants;s private.competency_test_sessions;a public.applications;
begin
 if session_hash is null or octet_length(session_hash)<>32 then raise exception using errcode='PT404',message='Resource unavailable';end if;
 select * into s from private.competency_test_sessions where session_digest=session_hash;
 a:=private.competency_lock_application(s.application_id);
 select * into g from private.competency_test_grants where id=s.grant_id for update nowait;
 select * into s from private.competency_test_sessions where session_digest=session_hash;
 if s.id is null or g.id is null or g.revoked_at is not null or s.invalidated_at is not null or s.grant_revision<>g.revision
  or clock_timestamp()>=least(s.absolute_expires_at,s.idle_expires_at) then raise exception using errcode='PT404',message='Resource unavailable';end if;
 perform private.competency_eligible(a,g.definition_entry_id);
 return g;
exception when lock_not_available then raise exception using errcode='PT409',message='Resource busy';end;$$;

create function private.inspect_candidate_competency_test(session_hash bytea) returns jsonb
language plpgsql security definer set search_path='' as $$
declare g private.competency_test_grants;a public.competency_test_attempts;d public.exercise_definition_entries;draft private.competency_test_drafts;
begin
 g:=private.competency_session(session_hash);
 select * into a from public.competency_test_attempts where grant_id=g.id for update nowait;
 if a.state='submitted' then return jsonb_build_object('state','submitted','attemptId',a.id);end if;
 select * into d from public.exercise_definition_entries where id=g.definition_entry_id;
 if a.id is null then
  if clock_timestamp()>=g.start_by_at then raise exception using errcode='PT404',message='Resource unavailable';end if;
  return jsonb_build_object('state','not_started','revisionId',d.id,'version',d.version,'durationMinutes',d.definition->'durationMinutes','label','Test kompetencji');end if;
 if clock_timestamp()>=a.deadline_at then raise exception using errcode='PT404',message='Resource unavailable';end if;
 select * into draft from private.competency_test_drafts where attempt_id=a.id;
 return jsonb_build_object('state','in_progress','attemptId',a.id,'startedAt',a.started_at,'deadlineAt',a.deadline_at,
 'test',jsonb_build_object('revisionId',d.id,'version',d.version,'title',d.definition->'title','instructions',d.definition->'instructions',
 'expectedOutput',d.definition->'expectedOutput','durationMinutes',d.definition->'durationMinutes'),
 'draft',jsonb_build_object('text',coalesce(draft.draft_text,''),'version',coalesce(draft.version,0)));
end;$$;
create function private.start_candidate_competency_test(session_hash bytea,request_key uuid) returns jsonb
language plpgsql security definer set search_path='' as $$
declare g private.competency_test_grants;a public.competency_test_attempts;app public.applications;d public.exercise_definition_entries;started timestamptz;
begin
 g:=private.competency_session(session_hash);
 if request_key is null then raise exception using errcode='PT422',message='Invalid request';end if;
 select * into a from public.competency_test_attempts where grant_id=g.id for update nowait;
 if a.id is not null then return private.inspect_candidate_competency_test(session_hash);end if;
 select * into app from public.applications where id=g.application_id;
 d:=private.competency_eligible(app,g.definition_entry_id);started:=clock_timestamp();
 if started>=g.start_by_at then raise exception using errcode='PT404',message='Resource unavailable';end if;
 insert into public.competency_test_attempts(company_id,candidate_id,recruitment_id,application_id,definition_entry_id,grant_id,started_at,deadline_at,start_request_key)
 values(g.company_id,g.candidate_id,g.recruitment_id,g.application_id,g.definition_entry_id,g.id,started,
 started+(d.definition->>'durationMinutes')::integer*interval '1 minute',request_key) returning * into a;
 update private.competency_test_sessions set absolute_expires_at=a.deadline_at+interval '15 minutes',idle_expires_at=a.deadline_at+interval '15 minutes'
 where grant_id=g.id and grant_revision=g.revision and invalidated_at is null;
 -- Transport buffers this result and exposes it only after a successful COMMIT.
 return private.inspect_candidate_competency_test(session_hash);
end;$$;
create function private.save_candidate_competency_test_draft(session_hash bytea,draft_text text,expected_version bigint,request_key uuid) returns jsonb
language plpgsql security definer set search_path='' as $$
declare g private.competency_test_grants;a public.competency_test_attempts;d private.competency_test_drafts;
begin
 g:=private.competency_session(session_hash);
 select * into a from public.competency_test_attempts where grant_id=g.id for update nowait;
 if a.id is null or a.state<>'in_progress' or clock_timestamp()>=a.deadline_at then raise exception using errcode='PT409',message='Attempt unavailable';end if;
 if draft_text is null or length(draft_text)>20000 or expected_version is null or expected_version<0 or request_key is null then raise exception using errcode='PT422',message='Invalid draft';end if;
 select * into d from private.competency_test_drafts where attempt_id=a.id;
 if d.request_key=request_key and d.version=expected_version+1 and d.draft_text=draft_text then return jsonb_build_object('version',d.version);end if;
 if coalesce(d.version,0)<>expected_version or d.request_key=request_key then raise exception using errcode='PT409',message='Draft changed';end if;
 insert into private.competency_test_drafts(company_id,candidate_id,recruitment_id,application_id,definition_entry_id,attempt_id,draft_text,version,request_key)
 values(g.company_id,g.candidate_id,g.recruitment_id,g.application_id,g.definition_entry_id,a.id,draft_text,expected_version+1,request_key)
 on conflict(attempt_id) do update set draft_text=excluded.draft_text,version=excluded.version,request_key=excluded.request_key;
 return jsonb_build_object('version',expected_version+1);
end;$$;
create function private.submit_candidate_competency_test(session_hash bytea,answer jsonb,request_key uuid) returns jsonb
language plpgsql security definer set search_path='' as $$
declare g private.competency_test_grants;a public.competency_test_attempts;canonical text;hash bytea;
begin
 g:=private.competency_session(session_hash);
 select * into a from public.competency_test_attempts where grant_id=g.id for update nowait;
 if a.id is null then raise exception using errcode='PT404',message='Resource unavailable';end if;
 if request_key is null then raise exception using errcode='PT422',message='Invalid request';end if;
 canonical:=private.competency_answer(answer);hash:=extensions.digest(canonical,'sha256');
 if a.state='submitted' then
  if a.submission_digest<>hash then raise exception using errcode='PT409',message='Already submitted';end if;
  return jsonb_build_object('state','submitted','attemptId',a.id);end if;
 if clock_timestamp()>=a.deadline_at then raise exception using errcode='PT409',message='Attempt expired';end if;
 update public.competency_test_attempts set state='submitted',work_sample=canonical,submission_digest=hash,submitted_at=clock_timestamp() where id=a.id;
 delete from private.competency_test_drafts where attempt_id=a.id;
 return jsonb_build_object('state','submitted','attemptId',a.id);
end;$$;
create function private.status_candidate_competency_test(session_hash bytea) returns jsonb
language plpgsql security definer set search_path='' as $$declare g private.competency_test_grants;a public.competency_test_attempts;begin
 g:=private.competency_session(session_hash);
 select * into a from public.competency_test_attempts where grant_id=g.id;
 if a.state is distinct from 'submitted' then raise exception using errcode='PT404',message='Resource unavailable';end if;
 return jsonb_build_object('state','submitted','attemptId',a.id);end;$$;

create function public.read_competency_test_response(target uuid) returns jsonb
language plpgsql security definer set search_path='' as $$
declare a public.competency_test_attempts;app public.applications;g private.competency_test_grants;
begin
 select * into a from public.competency_test_attempts where id=target;
 app:=private.competency_lock_application(a.application_id,true);
 select * into g from private.competency_test_grants where id=a.grant_id for update nowait;
 select * into a from public.competency_test_attempts where id=target for update nowait;
 if a.state is distinct from 'submitted' then raise exception using errcode='PT404',message='Resource unavailable';end if;
 return jsonb_build_object('attemptId',a.id,'workSample',a.work_sample,'definitionId',a.definition_entry_id,
 'companyId',a.company_id,'applicationId',a.application_id,'recruitmentId',a.recruitment_id,
 'reviews',(select coalesce(jsonb_agg(to_jsonb(r) order by version),'[]'::jsonb) from public.competency_test_review_entries r where attempt_id=a.id));
end;$$;

-- Staff-only index. Candidate gateway, viewers and other firms have no access.
-- Check withdrawal/restore and membership using the same locks as response reads.
create function private.competency_staff_attempt_index(target uuid) returns jsonb
language plpgsql security definer set search_path='' as $$
declare app public.applications;
begin
 app:=private.competency_lock_application(target,true);
 return (select coalesce(jsonb_agg(jsonb_build_object('id',s.id,'state',s.state,'version',s.version)
   order by s.started_at desc,s.id),'[]'::jsonb) from (
   select a.id,a.state,d.version,a.started_at from public.competency_test_attempts a
   join public.exercise_definition_entries d on d.id=a.definition_entry_id and d.company_id=a.company_id and d.recruitment_id=a.recruitment_id
   where a.company_id=app.company_id and a.candidate_id=app.candidate_id and a.application_id=app.id
     and a.recruitment_id=app.recruitment_id order by a.started_at desc,a.id limit 50
 ) s);
end;$$;
create function public.list_competency_test_attempts(target uuid) returns jsonb
language sql security invoker set search_path='' return private.competency_staff_attempt_index(target);
create function public.save_competency_test_review(target uuid,expected_version bigint,observations jsonb) returns uuid
language plpgsql security definer set search_path='' as $$
declare a public.competency_test_attempts;d public.exercise_definition_entries;v bigint;scored jsonb;result uuid;
begin
 perform public.read_competency_test_response(target);
 select * into a from public.competency_test_attempts where id=target;
 select * into d from public.exercise_definition_entries where id=a.definition_entry_id;
 select coalesce(max(version),0) into v from public.competency_test_review_entries where attempt_id=a.id;
 if expected_version is null or v<>expected_version then raise exception using errcode='PT409',message='Review changed';end if;
 scored:=private.competency_score(d.definition,a.work_sample,observations);
 insert into public.competency_test_review_entries(company_id,candidate_id,recruitment_id,application_id,definition_entry_id,attempt_id,
 reviewer_id,version,submission_digest,policy_version,observations,coverage,score,status)
 values(a.company_id,a.candidate_id,a.recruitment_id,a.application_id,a.definition_entry_id,a.id,auth.uid(),v+1,a.submission_digest,
 scored->>'policyVersion',scored->'criterionResults',(scored->>'coverage')::numeric,(scored->>'score')::numeric,scored->>'status') returning id into result;
 return result;
end;$$;

create function private.competency_protect_history() returns trigger
language plpgsql security invoker set search_path='' as $$
begin
 if tg_op='DELETE' and current_user='erasure_purge_owner' and private.erasure_purge_allowed(tg_table_schema||'.'||tg_table_name,to_jsonb(old)) then return old;end if;
 raise exception using errcode='42501',message='Competency history immutable';
end;$$;
create function private.competency_protect_attempt() returns trigger
language plpgsql security invoker set search_path='' as $$
begin
 if tg_op='DELETE' and current_user='erasure_purge_owner' and private.erasure_purge_allowed(tg_table_schema||'.'||tg_table_name,to_jsonb(old)) then return old;end if;
 if tg_op='UPDATE' and old.state='in_progress' and new.state='submitted'
 and (to_jsonb(new)-array['state','work_sample','submission_digest','submitted_at'])=(to_jsonb(old)-array['state','work_sample','submission_digest','submitted_at'])
 and new.submission_digest=extensions.digest(new.work_sample,'sha256') then return new;end if;
 raise exception using errcode='42501',message='Attempt immutable';end;$$;
create trigger competency_immutable before update or delete on public.competency_test_attempts for each row execute function private.competency_protect_attempt();
create trigger competency_immutable before update or delete on public.competency_test_review_entries for each row execute function private.competency_protect_history();
create trigger competency_immutable before update or delete on private.competency_test_grant_events for each row execute function private.competency_protect_history();
create trigger competency_immutable before update or delete on private.competency_test_cancellations for each row execute function private.competency_protect_history();
create trigger competency_no_delete before delete on private.competency_test_grants for each row execute function private.competency_protect_history();

-- Strip hostile default ACLs, not only the usual two API roles. Every function
-- starts private; the exact exposed surfaces below are the only grants.
do $$declare r record;g record;begin
 for r in select c.oid,n.nspname,c.relname from pg_class c join pg_namespace n on n.oid=c.relnamespace
 where n.nspname in ('public','private') and c.relname like 'competency_test_%' and c.relkind='r' loop
  execute format('alter table %s enable row level security',r.oid::regclass);
  for g in select distinct x.grantee,role.rolname from pg_class c cross join lateral aclexplode(coalesce(c.relacl,acldefault('r',c.relowner))) x
   left join pg_roles role on role.oid=x.grantee where c.oid=r.oid and x.grantee<>c.relowner loop
   if g.grantee=0 then execute format('revoke all on table %s from public',r.oid::regclass);
   else execute format('revoke all on table %s from %I',r.oid::regclass,g.rolname);end if;
  end loop;
  if r.relname<>'competency_test_cancellations' then execute format('create index %I on %s(company_id,candidate_id)',r.relname||'_candidate',r.oid::regclass);end if;
 end loop;
 for r in select p.oid,p.proowner from pg_proc p join pg_namespace n on n.oid=p.pronamespace
 where n.nspname in ('public','private') and (p.proname like 'competency_%' or p.proname like '%competency_test%') loop
  for g in select distinct x.grantee,role.rolname from pg_proc p cross join lateral aclexplode(coalesce(p.proacl,acldefault('f',p.proowner))) x
   left join pg_roles role on role.oid=x.grantee where p.oid=r.oid and x.grantee<>r.proowner loop
   if g.grantee=0 then execute format('revoke all on function %s from public',r.oid::regprocedure);
   else execute format('revoke all on function %s from %I',r.oid::regprocedure,g.rolname);end if;
  end loop;
 end loop;
end;$$;
create index competency_cancellation_candidates on private.competency_test_cancellations using gin(candidate_ids);
grant execute on function public.create_competency_test_grant(uuid,uuid,timestamptz,uuid),
 public.get_competency_test_grant_status(uuid),public.rotate_competency_test_grant(uuid,bigint,uuid),
 public.revoke_competency_test_grant(uuid,uuid),public.read_competency_test_response(uuid),
 public.save_competency_test_review(uuid,bigint,jsonb),public.list_competency_test_attempts(uuid),
 private.competency_staff_attempt_index(uuid) to authenticated;
grant execute on function private.exchange_candidate_competency_test_session(text),
 private.inspect_candidate_competency_test(bytea),private.start_candidate_competency_test(bytea,uuid),
 private.save_candidate_competency_test_draft(bytea,text,bigint,uuid),private.submit_candidate_competency_test(bytea,jsonb,uuid),
 private.status_candidate_competency_test(bytea) to competency_test_gateway;


-- Controlled withdrawal and immutable markers.

-- The exception is an ungrantable NOLOGIN capability, not a spoofable GUC.
-- The trigger is intentionally SECURITY INVOKER: current_user is the caller
-- executing the UPDATE, not the installer who owns this trigger function.
create function private.competency_marker_guard() returns trigger
language plpgsql security invoker set search_path='' as $$
begin
 if tg_op='INSERT' then
  if new.competency_access_cancelled_at is not null or new.competency_access_cancel_reason is not null
   or (tg_table_name='applications' and to_jsonb(new)->>'status'='withdrawn') then
   raise exception using errcode='42501',message='Controlled competency withdrawal required';end if;
 else
  if row(new.competency_access_cancelled_at,new.competency_access_cancel_reason) is distinct from
   row(old.competency_access_cancelled_at,old.competency_access_cancel_reason)
   and (current_user<>'competency_test_marker_writer' or old.competency_access_cancelled_at is not null
    or new.competency_access_cancelled_at is null or new.competency_access_cancel_reason is null) then
   raise exception using errcode='42501',message='Competency withdrawal marker is immutable';end if;
  if tg_table_name='applications' and to_jsonb(new)->>'status'='withdrawn'
   and to_jsonb(old)->>'status' is distinct from 'withdrawn'
   and current_user<>'competency_test_marker_writer' then
   raise exception using errcode='42501',message='Controlled competency withdrawal required';end if;
 end if;
 return new;
end;$$;
revoke all on function private.competency_marker_guard() from public,anon,authenticated;
create trigger competency_candidate_marker_guard before insert or update on public.candidates
 for each row execute function private.competency_marker_guard();
create trigger competency_application_marker_guard before insert or update on public.applications
 for each row execute function private.competency_marker_guard();

grant usage on schema public,private to competency_test_marker_writer;
grant select on public.candidates,public.applications to competency_test_marker_writer;
grant update(competency_access_cancelled_at,competency_access_cancel_reason) on public.candidates to competency_test_marker_writer;
grant update(status,competency_access_cancelled_at,competency_access_cancel_reason) on public.applications to competency_test_marker_writer;
grant execute on function private.erasure_normal_row_guard(text,text,text,jsonb,jsonb) to competency_test_marker_writer;
create policy competency_marker_read on public.candidates for select to competency_test_marker_writer using(true);
create policy competency_marker_write on public.candidates for update to competency_test_marker_writer using(true) with check(true);
create policy competency_marker_read on public.applications for select to competency_test_marker_writer using(true);
create policy competency_marker_write on public.applications for update to competency_test_marker_writer using(true) with check(true);

create function private.competency_write_markers(tenant uuid,subjects uuid[],application_ids uuid[],reason text,
 mark_candidates boolean,withdraw_application boolean) returns void
language plpgsql security definer set search_path='' as $$
begin
 if reason is null or reason not in ('consent_withdrawn','candidate_withdrawn') then
  raise exception using errcode='PT422',message='Invalid withdrawal reason';end if;
 if mark_candidates then
  update public.candidates set competency_access_cancelled_at=coalesce(competency_access_cancelled_at,clock_timestamp()),
   competency_access_cancel_reason=coalesce(competency_access_cancel_reason,reason)
   where company_id=tenant and id=any(subjects);
 end if;
 update public.applications set competency_access_cancelled_at=coalesce(competency_access_cancelled_at,clock_timestamp()),
  competency_access_cancel_reason=coalesce(competency_access_cancel_reason,reason),
  status=case when withdraw_application then 'withdrawn' else status end
  where company_id=tenant and candidate_id=any(subjects) and id=any(application_ids);
end;$$;
-- PG16+ non-superuser creators retain ADMIN only. Ownership transfers need
-- SET plus schema CREATE, confined to this transaction and restored below.
create temporary table sc_wer_marker_migration_access on commit drop as
 select (select rolsuper from pg_roles where rolname=current_user) superuser,
   (select coalesce(jsonb_agg(to_jsonb(m) order by m.roleid,m.member,m.grantor),'[]'::jsonb)
    from pg_auth_members m where m.roleid='competency_test_marker_writer'::regrole or m.member='competency_test_marker_writer'::regrole) memberships,
   (select nspacl from pg_namespace where nspname='private') schema_acl;
do $$begin
 if current_user<>session_user then raise exception 'Migration identity must be direct';end if;
 if has_schema_privilege('competency_test_marker_writer','private','CREATE') then
   raise exception 'Unsafe purge owner schema privileges';
 end if;
 if not (select superuser from pg_temp.sc_wer_marker_migration_access) then
   if current_user<>'postgres' or exists(select 1 from pg_auth_members m
     where (m.roleid='competency_test_marker_writer'::regrole or m.member='competency_test_marker_writer'::regrole)
       and not (current_user='postgres' and current_setting('server_version_num')::integer/10000 in (16,17)
          and m.roleid='competency_test_marker_writer'::regrole and exists(select 1 from pg_roles where oid=m.member and rolname='postgres' and not rolsuper and rolinherit and rolcreaterole and rolcreatedb and rolcanlogin and rolreplication and rolbypassrls)
          and exists(select 1 from pg_roles where oid=m.grantor and rolname='supabase_admin' and oid=10 and rolsuper and rolinherit and rolcreaterole and rolcreatedb and rolcanlogin and rolreplication and rolbypassrls)
          and m.admin_option and not m.inherit_option and not m.set_option)) or not exists(select 1 from pg_auth_members m where (current_user='postgres' and current_setting('server_version_num')::integer/10000 in (16,17)
          and m.roleid='competency_test_marker_writer'::regrole and exists(select 1 from pg_roles where oid=m.member and rolname='postgres' and not rolsuper and rolinherit and rolcreaterole and rolcreatedb and rolcanlogin and rolreplication and rolbypassrls)
          and exists(select 1 from pg_roles where oid=m.grantor and rolname='supabase_admin' and oid=10 and rolsuper and rolinherit and rolcreaterole and rolcreatedb and rolcanlogin and rolreplication and rolbypassrls)
          and m.admin_option and not m.inherit_option and not m.set_option)) then
     raise exception 'Unsafe purge owner migration membership';
   end if;
   grant competency_test_marker_writer to postgres with admin false, inherit false, set true;
 end if;
 grant create on schema private to competency_test_marker_writer;
end;$$;

alter function private.competency_write_markers(uuid,uuid[],uuid[],text,boolean,boolean) owner to competency_test_marker_writer;
set local role competency_test_marker_writer;
-- Only trusted postgres-owned domain functions may invoke the marker writer.
do $$declare g record;begin
 for g in select distinct a.grantee,r.rolname from pg_proc p
 cross join lateral aclexplode(coalesce(p.proacl,acldefault('f',p.proowner))) a
 left join pg_roles r on r.oid=a.grantee where p.oid='private.competency_write_markers(uuid,uuid[],uuid[],text,boolean,boolean)'::regprocedure and a.grantee<>p.proowner loop
 if g.grantee=0 then revoke all on function private.competency_write_markers(uuid,uuid[],uuid[],text,boolean,boolean) from public;
 else execute format('revoke all on function private.competency_write_markers(uuid,uuid[],uuid[],text,boolean,boolean) from %I',g.rolname);end if;
 end loop;
end;$$;
grant execute on function private.competency_write_markers(uuid,uuid[],uuid[],text,boolean,boolean) to postgres;
reset role;
do $$begin
 revoke create on schema private from competency_test_marker_writer;
 if not (select superuser from pg_temp.sc_wer_marker_migration_access) then
   revoke competency_test_marker_writer from postgres granted by postgres;
 end if;
 if (select nspacl from pg_namespace where nspname='private') is distinct from
      (select schema_acl from pg_temp.sc_wer_marker_migration_access) or
   has_schema_privilege('competency_test_marker_writer','private','CREATE') or
   (select coalesce(jsonb_agg(to_jsonb(m) order by m.roleid,m.member,m.grantor),'[]'::jsonb)
    from pg_auth_members m where m.roleid='competency_test_marker_writer'::regrole or m.member='competency_test_marker_writer'::regrole)
      is distinct from (select memberships from pg_temp.sc_wer_marker_migration_access) then
   raise exception 'Purge migration privileges not restored';
 end if;
end;$$;


-- Include historical ranges as well as the latest revision. Shrinking a range
-- or switching its anchor cannot detach an already persisted withdrawal.
create function private.competency_resolution_closure(tenant uuid,subjects uuid[]) returns uuid[]
language sql volatile security definer set search_path='' as $$
 with recursive linked(id) as (
  select unnest(subjects)
  union
  select member.id from linked l join private.erasure_subject_resolutions r
   on r.company_id=tenant and l.id=any(array_append(r.candidate_ids,r.anchor_candidate_id))
   cross join lateral unnest(array_append(r.candidate_ids,r.anchor_candidate_id)) member(id)
 ) select array_agg(id order by id) from linked
$$;
revoke all on function private.competency_resolution_closure(uuid,uuid[]) from public,anon,authenticated;

-- For every publisher of a resolution, old and new ranges share candidate
-- locks. Applications precede the company authority lock, avoiding the former
-- company -> candidate inversion in confirm_erasure_subject.
create function private.competency_lock_resolution(tenant uuid,subjects uuid[]) returns uuid[]
language plpgsql volatile security definer set search_path='' as $$
declare locked_ids uuid[];subject uuid;application_id uuid;
begin
 if auth.uid() is null or not exists(select 1 from public.companies where id=tenant and owner_id=auth.uid()) then
  raise exception using errcode='PT404',message='Resource unavailable';end if;
 locked_ids:=private.competency_resolution_closure(tenant,subjects);
 if cardinality(locked_ids)>100 then raise exception using errcode='PT409',message='Subject resolution required';end if;
 foreach subject in array locked_ids loop
  perform private.erasure_lock_candidate(subject);
  if not exists(select 1 from public.candidates where id=subject and company_id=tenant) then
   raise exception using errcode='PT404',message='Resource unavailable';end if;
 end loop;
 perform 1 from private.erasure_execution_config where singleton for share nowait;
 if exists(select 1 from private.erasure_execution_config where singleton and restore_isolated) then
  raise exception using errcode='PT409',message='Restore isolation required';end if;
 if locked_ids is distinct from private.competency_resolution_closure(tenant,subjects) then
  raise exception using errcode='PT409',message='Subject resolution changed';end if;
 for application_id in select a.id from public.applications a where a.company_id=tenant and a.candidate_id=any(locked_ids) order by a.id loop
  perform 1 from public.applications where id=application_id for update nowait;
 end loop;
 perform private.competency_authority(tenant,true);
 return locked_ids;
exception when lock_not_available then raise exception using errcode='PT409',message='Subject resolution busy';end;$$;
revoke all on function private.competency_lock_resolution(uuid,uuid[]) from public,anon,authenticated;

-- Called only after all candidate/application/authority locks have been taken.
-- Every revoke gets its own event key; the cancellation row ties the complete
-- affected set to the caller's idempotency key in this same transaction.
create function private.competency_revoke_applications(tenant uuid,application_ids uuid[]) returns void
language plpgsql security definer set search_path='' as $$
declare grant_id uuid;
begin
 for grant_id in select g.id from private.competency_test_grants g
  where g.company_id=tenant and g.application_id=any(application_ids) order by g.id loop
  perform public.revoke_competency_test_grant(grant_id,gen_random_uuid());
 end loop;
end;$$;
revoke all on function private.competency_revoke_applications(uuid,uuid[]) from public,anon,authenticated;

-- This trigger also protects an INSERT made by a future trusted importer or
-- helper. There is no executable public bypass around resolution propagation.
create function private.competency_resolution_insert_guard() returns trigger
language plpgsql security definer set search_path='' as $$
declare ids uuid[];locked_ids uuid[];application_ids uuid[];latest bigint;reason text;
begin
 if new.candidate_ids is null or cardinality(new.candidate_ids) not between 1 and 100
  or array_ndims(new.candidate_ids)<>1 or array_position(new.candidate_ids,null) is not null
  or not new.anchor_candidate_id=any(new.candidate_ids) then
  raise exception using errcode='PT422',message='Invalid subject resolution';end if;
 select array_agg(distinct id order by id) into ids from unnest(new.candidate_ids) x(id);
 if cardinality(ids)<>cardinality(new.candidate_ids) then raise exception using errcode='PT422',message='Duplicate candidate IDs';end if;
 locked_ids:=private.competency_lock_resolution(new.company_id,ids);
 if new.confirmed_by is distinct from auth.uid() then raise exception using errcode='PT404',message='Resource unavailable';end if;
 select coalesce(max(r.revision),0) into latest from private.erasure_subject_resolutions r
  where r.company_id=new.company_id and r.anchor_candidate_id=new.anchor_candidate_id;
 if new.revision<>latest+1 then raise exception using errcode='PT409',message='Subject resolution changed';end if;
 select c.competency_access_cancel_reason into reason from public.candidates c
  where c.company_id=new.company_id and c.id=any(locked_ids) and c.competency_access_cancelled_at is not null order by c.id limit 1;
 if found then
  -- A new A/C link can join existing A/B and C/D resolutions. All confirmed
  -- members of the already locked transitive closure inherit the denial,
  -- including D which is absent from this INSERT's candidate_ids payload.
  select coalesce(array_agg(a.id order by a.id),'{}'::uuid[]) into application_ids from public.applications a
   where a.company_id=new.company_id and a.candidate_id=any(locked_ids);
  perform private.competency_revoke_applications(new.company_id,application_ids);
  perform private.competency_write_markers(new.company_id,locked_ids,application_ids,reason,true,false);
  insert into private.competency_test_cancellations(company_id,candidate_ids,scope_kind,resolution_id,resolution_revision,reason,actor_id,request_key)
   values(new.company_id,locked_ids,'resolution_link',new.id,new.revision,reason,auth.uid(),gen_random_uuid());
 end if;
 new.candidate_ids:=ids;
 return new;
exception when lock_not_available then raise exception using errcode='PT409',message='Subject resolution busy';end;$$;
revoke all on function private.competency_resolution_insert_guard() from public,anon,authenticated;
create trigger competency_resolution_insert_guard before insert on private.erasure_subject_resolutions
 for each row execute function private.competency_resolution_insert_guard();

create or replace function public.confirm_erasure_subject(target_candidate uuid,candidate_ids uuid[],expected_revision bigint,request_key uuid)
returns uuid language plpgsql volatile security definer set search_path='' as $$
declare tenant uuid;ids uuid[];latest bigint;payload text;old private.erasure_configuration_requests;result uuid;
begin
 if current_setting('transaction_isolation') not in ('read committed','read uncommitted') then
  raise exception using errcode='PT409',message='Fresh transaction required';end if;
 if expected_revision is null or expected_revision<0 or request_key is null or candidate_ids is null
  or cardinality(candidate_ids) not between 1 and 100 or array_ndims(candidate_ids)<>1 or array_position(candidate_ids,null) is not null
  or target_candidate is null or not target_candidate=any(candidate_ids) then
  raise exception using errcode='PT422',message='Invalid subject resolution';end if;
 select array_agg(distinct x order by x) into ids from unnest(candidate_ids) x;
 if cardinality(ids)<>cardinality(candidate_ids) then raise exception using errcode='PT422',message='Duplicate candidate IDs';end if;
 select company_id into tenant from public.candidates where id=target_candidate;
 perform private.competency_lock_resolution(tenant,ids);
 payload:=private.erasure_hash(jsonb_build_array(target_candidate,ids,expected_revision));
 select * into old from private.erasure_configuration_requests where company_id=tenant and actor_id=auth.uid()
  and operation='resolution' and erasure_configuration_requests.request_key=confirm_erasure_subject.request_key;
 if found then
  if old.payload_hash<>payload then raise exception using errcode='PT409',message='Request key reused';end if;
  return old.result_id;
 end if;
 select coalesce(max(revision),0) into latest from private.erasure_subject_resolutions where company_id=tenant and anchor_candidate_id=target_candidate;
 if latest<>expected_revision then raise exception using errcode='PT409',message='Subject revision changed';end if;
 insert into private.erasure_subject_resolutions(company_id,anchor_candidate_id,candidate_ids,revision,confirmed_by)
  values(tenant,target_candidate,ids,latest+1,auth.uid()) returning id into result;
 insert into private.erasure_configuration_requests values(tenant,auth.uid(),'resolution',request_key,payload,result,now());
 return result;
exception when lock_not_available or unique_violation then raise exception using errcode='PT409',message='Subject changed';end;$$;
revoke all on function public.confirm_erasure_subject(uuid,uuid[],bigint,uuid) from public,anon,authenticated;
grant execute on function public.confirm_erasure_subject(uuid,uuid[],bigint,uuid) to authenticated;

-- Scope is explicit and closed: {kind:'application',application_id,reason} or
-- {kind:'confirmed_subject',resolution_id,resolution_revision,reason}. IDs in
-- a confirmed subject always come from the immutable server resolution.
create function public.withdraw_competency_test_access(scope jsonb,request_key uuid) returns jsonb
language plpgsql volatile security definer set search_path='' as $$
declare kind text;reason text;app public.applications;r private.erasure_subject_resolutions;expected_revision bigint;
 tenant uuid;ids uuid[];subject uuid;application_ids uuid[];application_id uuid;old private.competency_test_cancellations;
 result uuid;resolution_id uuid;
begin
 if request_key is null or jsonb_typeof(scope) is distinct from 'object' then
  raise exception using errcode='PT422',message='Invalid withdrawal scope';end if;
 kind:=scope->>'kind';reason:=scope->>'reason';
 if reason is null or reason not in ('candidate_withdrawn','consent_withdrawn') then
  raise exception using errcode='PT422',message='Invalid withdrawal reason';end if;
 if kind='application' then
  if (scope-array['kind','application_id','reason'])<>'{}'::jsonb or scope->>'application_id' is null
   or reason<>'candidate_withdrawn' then raise exception using errcode='PT422',message='Invalid application withdrawal';end if;
  app:=private.competency_lock_application((scope->>'application_id')::uuid,true,true);
  tenant:=app.company_id;ids:=array[app.candidate_id];application_ids:=array[app.id];
 elsif kind='confirmed_subject' then
  if (scope-array['kind','resolution_id','resolution_revision','reason'])<>'{}'::jsonb or scope->>'resolution_id' is null
   or jsonb_typeof(scope->'resolution_revision') is distinct from 'number' or scope->>'resolution_revision' !~ '^[1-9][0-9]*$' then
   raise exception using errcode='PT422',message='Invalid subject withdrawal';end if;
  resolution_id:=(scope->>'resolution_id')::uuid;expected_revision:=(scope->>'resolution_revision')::bigint;
  select * into r from private.erasure_subject_resolutions where id=resolution_id;
  if not found then raise exception using errcode='PT409',message='Subject resolution required';end if;
  tenant:=r.company_id;ids:=r.candidate_ids;
  if auth.uid() is null or not exists(select 1 from public.companies where id=tenant and owner_id=auth.uid()) then
   raise exception using errcode='PT404',message='Resource unavailable';end if;
  foreach subject in array ids loop
   perform private.erasure_lock_candidate(subject);
   if not exists(select 1 from public.candidates where id=subject and company_id=tenant) then
    raise exception using errcode='PT409',message='Subject resolution changed';end if;
  end loop;
  perform 1 from private.erasure_execution_config where singleton for share nowait;
  if exists(select 1 from private.erasure_execution_config where singleton and restore_isolated) then
   raise exception using errcode='PT409',message='Restore isolation required';end if;
  select * into r from private.erasure_subject_resolutions where id=resolution_id for share nowait;
  if r.id is null or r.company_id<>tenant or r.candidate_ids is distinct from ids or r.revision<>expected_revision
   or r.revision<>(select max(revision) from private.erasure_subject_resolutions where company_id=tenant and anchor_candidate_id=r.anchor_candidate_id)
   or ids is distinct from private.competency_resolution_closure(tenant,ids) then
   raise exception using errcode='PT409',message='Subject resolution changed';end if;
  select coalesce(array_agg(a.id order by a.id),'{}'::uuid[]) into application_ids from public.applications a
   where a.company_id=tenant and a.candidate_id=any(ids);
  foreach application_id in array application_ids loop
   perform 1 from public.applications where id=application_id for update nowait;
  end loop;
  perform private.competency_authority(tenant,true);
  if r.confirmed_by is distinct from auth.uid() then raise exception using errcode='PT409',message='Subject resolution required';end if;
 else raise exception using errcode='PT422',message='Invalid withdrawal scope';
 end if;
 select * into old from private.competency_test_cancellations c where c.company_id=tenant and c.actor_id=auth.uid()
  and c.request_key=withdraw_competency_test_access.request_key;
 if found then
  if old.scope_kind<>kind or old.reason<>reason or old.candidate_ids is distinct from ids
   or old.application_id is distinct from app.id or old.resolution_id is distinct from resolution_id
   or old.resolution_revision is distinct from expected_revision then raise exception using errcode='PT409',message='Request key reused';end if;
  return jsonb_build_object('withdrawn',true,'cancellationId',old.id,'scope',kind);
 end if;
 perform private.competency_revoke_applications(tenant,application_ids);
 perform private.competency_write_markers(tenant,ids,application_ids,reason,kind='confirmed_subject',kind='application');
 insert into private.competency_test_cancellations(company_id,candidate_ids,application_id,scope_kind,resolution_id,resolution_revision,reason,actor_id,request_key)
  values(tenant,ids,app.id,kind,resolution_id,expected_revision,reason,auth.uid(),request_key) returning id into result;
 return jsonb_build_object('withdrawn',true,'cancellationId',result,'scope',kind);
exception when invalid_text_representation or numeric_value_out_of_range then raise exception using errcode='PT422',message='Invalid withdrawal scope';
 when lock_not_available or unique_violation then raise exception using errcode='PT409',message='Withdrawal busy';end;$$;
revoke all on function public.withdraw_competency_test_access(jsonb,uuid) from public,anon,authenticated;
grant execute on function public.withdraw_competency_test_access(jsonb,uuid) to authenticated;

-- Existing withdrawn rows must be safe before this composition can activate.
-- The fresh isolated B2 tables cannot contain prior grants. Fail closed if the
-- caller tries to apply this installation step to a partially active schema.
-- This is an explicit installation backfill audit attributed to the tenant's
-- existing owner; it neither sets an auth claim nor impersonates that owner.
do $$declare app public.applications;actor uuid;subject uuid;application_id uuid;begin
 for subject in select distinct candidate_id from public.applications
  where status='withdrawn' and competency_access_cancelled_at is null order by candidate_id loop
  perform private.erasure_lock_candidate(subject);
 end loop;
 for application_id in select id from public.applications
  where status='withdrawn' and competency_access_cancelled_at is null order by id loop
  perform 1 from public.applications where id=application_id for update nowait;
 end loop;
 for app in select a.* from public.applications a where a.status='withdrawn' and a.competency_access_cancelled_at is null order by a.candidate_id,a.id loop
  if exists(select 1 from private.competency_test_grants g where g.application_id=app.id) then
   raise exception 'Historical withdrawn grant requires controlled reconciliation before installation';end if;
  select owner_id into actor from public.companies where id=app.company_id for share nowait;
  if actor is null then raise exception 'Historical withdrawal requires an auditable owner';end if;
  perform private.competency_write_markers(app.company_id,array[app.candidate_id],array[app.id],'candidate_withdrawn',false,true);
  insert into private.competency_test_cancellations(company_id,candidate_ids,application_id,scope_kind,reason,actor_id,request_key)
   values(app.company_id,array[app.candidate_id],app.id,'historical_withdrawn','candidate_withdrawn',actor,gen_random_uuid());
 end loop;
end;$$;

-- Do not inherit an installation's over-broad default function grants. The
-- marker writer cannot be assumed by an API role and its writer has no public
-- EXECUTE path. ACL cleanup is transactional with publication of these RPCs.
do $$declare f record;g record;begin
 for f in select p.oid,p.proowner from pg_proc p join pg_namespace n on n.oid=p.pronamespace
  where (n.nspname='private' and p.proname in ('competency_marker_guard',
   'competency_resolution_closure','competency_lock_resolution','competency_revoke_applications','competency_resolution_insert_guard'))
   or (n.nspname='public' and p.proname in ('confirm_erasure_subject','withdraw_competency_test_access')) loop
  for g in select distinct x.grantee,r.rolname from pg_proc p
   cross join lateral aclexplode(coalesce(p.proacl,acldefault('f',p.proowner))) x
   left join pg_roles r on r.oid=x.grantee where p.oid=f.oid and x.grantee<>f.proowner loop
   if g.grantee=0 then execute format('revoke all on function %s from public',f.oid::regprocedure);
   else execute format('revoke all on function %s from %I',f.oid::regprocedure,g.rolname);end if;
  end loop;
 end loop;
end;$$;
grant execute on function public.confirm_erasure_subject(uuid,uuid[],bigint,uuid),
 public.withdraw_competency_test_access(jsonb,uuid) to authenticated;


alter function private.erasure_inventory_rows(uuid,uuid[]) rename to erasure_inventory_rows_r11;
alter function private.erasure_row_candidates(text,jsonb) rename to erasure_row_candidates_r11;
create function private.erasure_row_candidates(adapter text,data jsonb) returns uuid[]
language plpgsql stable security definer set search_path='' as $$
declare ids uuid[];
begin
 if adapter in ('private.competency_test_grants','private.competency_test_grant_events','public.competency_test_attempts','private.competency_test_sessions','private.competency_test_drafts','public.competency_test_review_entries') then return array[(data->>'candidate_id')::uuid];end if;
 if adapter='private.competency_test_cancellations' then
  with refs as (
   select value::uuid id from jsonb_array_elements_text(data->'candidate_ids')
   union select a.candidate_id from public.applications a
    where a.company_id=(data->>'company_id')::uuid and a.id=(data->>'application_id')::uuid
  ) select array_agg(distinct id order by id) into ids from refs;
  if coalesce(cardinality(ids),0)=0 or array_position(ids,null) is not null then
   raise exception using errcode='PT409',message='Unknown competency cancellation dependency';end if;
  return ids;
 end if;
 return private.erasure_row_candidates_r11(adapter,data);
end;$$;
create function private.erasure_inventory_rows(tenant uuid,subjects uuid[])
returns table(adapter text,row_key text,row_data jsonb) language sql stable security definer set search_path='' set timezone='UTC' set datestyle='ISO, YMD' as $$
 select * from private.erasure_inventory_rows_r11(tenant,subjects)
 union all select 'private.competency_test_grants',t.id::text,to_jsonb(t) from private.competency_test_grants t
 where t.company_id=tenant and (t.candidate_id=any(subjects))
 union all select 'private.competency_test_grant_events',t.id::text,to_jsonb(t) from private.competency_test_grant_events t
 where t.company_id=tenant and (t.candidate_id=any(subjects))
 union all select 'public.competency_test_attempts',t.id::text,to_jsonb(t) from public.competency_test_attempts t
 where t.company_id=tenant and (t.candidate_id=any(subjects))
 union all select 'private.competency_test_sessions',t.id::text,to_jsonb(t) from private.competency_test_sessions t
 where t.company_id=tenant and (t.candidate_id=any(subjects))
 union all select 'private.competency_test_drafts',t.id::text,to_jsonb(t) from private.competency_test_drafts t
 where t.company_id=tenant and (t.candidate_id=any(subjects))
 union all select 'public.competency_test_review_entries',t.id::text,to_jsonb(t) from public.competency_test_review_entries t
 where t.company_id=tenant and (t.candidate_id=any(subjects))
 union all select 'private.competency_test_cancellations',t.id::text,to_jsonb(t) from private.competency_test_cancellations t
 where t.company_id=tenant and (private.erasure_row_candidates('private.competency_test_cancellations',to_jsonb(t)) && subjects)
$$;
revoke all on function private.erasure_inventory_rows(uuid,uuid[]),private.erasure_row_candidates(text,jsonb) from public,anon,authenticated;
create table private.erasure_inventory_baseline_r12 (
 singleton boolean primary key default true check(singleton),schema_signature text not null,known_tables text[] not null
);
alter table private.erasure_inventory_baseline_r12 enable row level security;
create trigger immutable_history before update or delete on private.erasure_inventory_baseline_r12 for each row execute function private.contact_immutable();
insert into private.erasure_inventory_baseline_r12 select true,'48afc7b117acb3640b1521c9b8b2e525e89d653d9e2981edf2b1209f9515eaba',known_tables||array['private.competency_test_grants','private.competency_test_grant_events','public.competency_test_attempts','private.competency_test_sessions','private.competency_test_drafts','public.competency_test_review_entries','private.competency_test_cancellations','private.erasure_inventory_baseline_r12']
 from private.erasure_inventory_baseline_r11 where singleton;

create or replace function public.preview_candidate_erasure(target_candidate uuid,scope_kind text default 'candidate_record',resolution_id uuid default null)
returns jsonb language plpgsql stable security definer set search_path='' set timezone='UTC' set datestyle='ISO, YMD' as $$
declare tenant uuid;subjects uuid[];p private.candidate_retention_policies;r private.erasure_subject_resolutions;
 baseline private.erasure_inventory_baseline_r12;signature text;counts jsonb:='{}';manifest text;row_digest jsonb:='[]';
 blockers text[]:=array['execution_not_provisioned','external_inventory_unverified','backup_policy_unverified','administrative_inventory_pending_execution'];generated timestamptz:=statement_timestamp();
begin
 select company_id into tenant from public.candidates where id=target_candidate;perform private.erasure_owner(tenant);
 if scope_kind is null or scope_kind not in ('candidate_record','confirmed_subject')
 or (scope_kind='candidate_record' and resolution_id is not null) or (scope_kind='confirmed_subject' and resolution_id is null)
 then raise exception using errcode='PT422',message='Invalid preview scope';end if;
 subjects:=array[target_candidate];
 if scope_kind='confirmed_subject' then
  select * into r from private.erasure_subject_resolutions where id=resolution_id and company_id=tenant and anchor_candidate_id=target_candidate;
  if not found then raise exception using errcode='PT404',message='Resource unavailable';end if;
  subjects:=r.candidate_ids;
  if r.revision<>(select max(revision) from private.erasure_subject_resolutions where company_id=tenant and anchor_candidate_id=target_candidate)
   or r.confirmed_by<>auth.uid() then blockers:=array_append(blockers,'subject_resolution_changed');end if;
  if cardinality(subjects)<>(select count(*) from public.candidates where company_id=tenant and id=any(subjects)) then
   blockers:=array_append(blockers,'subject_resolution_changed');end if;
 else blockers:=array_append(blockers,'subject_resolution_required');end if;
 select * into p from private.candidate_retention_policies where company_id=tenant order by revision desc limit 1;
 if p.id is null then blockers:=array_append(blockers,'retention_policy_required');
 elsif jsonb_array_length(p.rules)<8 then blockers:=array_append(blockers,'retention_policy_incomplete');end if;
 if p.id is not null and p.approved_by<>auth.uid() then blockers:=array_append(blockers,'policy_owner_changed');end if;
 select * into baseline from private.erasure_inventory_baseline_r12 where singleton;
 signature:=private.erasure_schema_signature();
 if baseline.singleton is null or baseline.known_tables is null or signature is distinct from baseline.schema_signature or exists(
  select 1 from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname in ('public','private') and c.relkind in ('r','p','f')
  and not (n.nspname||'.'||c.relname)=any(baseline.known_tables)) then
  blockers:=array_append(blockers,'schema_dependency_unknown');
 else
  -- Preserve the R4-VOICE preview denial as well as its purge/restore adapters.
  -- The legacy R4 fixture has no voice module; SQL in this branch is planned
  -- only when the reviewed voice helper exists.
  if to_regprocedure('private.erasure_voice_request_candidate(uuid,text,uuid)') is not null then
    if exists(select 1 from private.voice_plan_request_keys t where t.company_id=tenant
      and private.erasure_voice_request_candidate(t.company_id,t.operation,t.result_id) is null)
    then blockers:=array_append(blockers,'voice_request_adapter_unknown');end if;
  end if;
  if exists(select 1 from private.contact_requests t where t.company_id=tenant
   and private.erasure_contact_request_candidate(t.company_id,t.operation,t.payload,t.result_id) is null) then blockers:=array_append(blockers,'contact_request_adapter_unknown');end if;
  if exists(select 1 from public.screening_analysis_versions a join public.applications ap on ap.company_id=a.company_id and ap.id=a.application_id
   where ap.company_id=tenant and ap.candidate_id=any(subjects) and a.execution_status in ('pending','processing')) then blockers:=array_append(blockers,'active_screening');end if;
  if exists(select 1 from private.erasure_subject_resolutions sr where sr.company_id=tenant and sr.candidate_ids && subjects and not sr.candidate_ids <@ subjects)
   then blockers:=array_append(blockers,'shared_resolution_requires_adapter');end if;
  if exists(select 1 from private.competency_test_cancellations c where c.company_id=tenant
   and private.erasure_row_candidates('private.competency_test_cancellations',to_jsonb(c)) && subjects
   and not private.erasure_row_candidates('private.competency_test_cancellations',to_jsonb(c)) <@ subjects)
   then blockers:=array_append(blockers,'shared_competency_cancellation_requires_adapter');end if;
  with rows as materialized(select * from private.erasure_inventory_rows(tenant,subjects)),
  grouped as(select adapter,count(*) n from rows group by adapter)
  select coalesce((select jsonb_object_agg(adapter,n) from grouped),'{}'::jsonb),
   coalesce((select jsonb_agg(jsonb_build_array(adapter,row_key,private.erasure_hash(row_data)) order by adapter,row_key) from rows),'[]'::jsonb)
  into counts,row_digest;
 end if;
 manifest:=private.erasure_hash(jsonb_build_object('contract','sc010-r1-v1','tenant',tenant,'owner',auth.uid(),'scope',scope_kind,'subjects',subjects,
 'resolution',to_jsonb(r),'current_resolution_revision',(select coalesce(max(revision),0) from private.erasure_subject_resolutions where company_id=tenant and anchor_candidate_id=target_candidate),
 'policy',to_jsonb(p),'schema',signature,'rows',row_digest,'blockers',blockers));
 return jsonb_build_object('scope_kind',scope_kind,'candidate_count',cardinality(subjects),'counts',counts,'blockers',to_jsonb(blockers),
 'policy_revision',coalesce(p.revision,0),'resolution_revision',coalesce(r.revision,0),'manifest_hash',manifest,'schema_signature',signature,
 'generated_at',generated,'expires_at',generated+interval '5 minutes','execution_enabled',false);
end;$$;

create or replace function private.prepare_erasure_purge_manifest(target_request uuid) returns jsonb
language plpgsql volatile security definer set search_path='' set timezone='UTC' set datestyle='ISO, YMD' as $$
declare e private.erasure_executions;digest text;signature text;counts jsonb;baseline text;
begin
 perform private.erasure_check_purge_scope(target_request);
 select * into e from private.erasure_executions where request_id=target_request;
 signature:=private.erasure_schema_signature();
 -- R4 final reviewed baseline is installed by the final migration, never learned at runtime.
 select schema_signature into baseline from private.erasure_inventory_baseline_r12 where singleton;
 if signature is distinct from baseline then raise exception using errcode='PT409',message='Unknown schema dependency';end if;
 select private.erasure_hash(coalesce(jsonb_agg(jsonb_build_array(adapter,row_key,private.erasure_hash(row_data)) order by adapter,row_key),'[]'::jsonb)) into digest from private.erasure_purge_rows(e.company_id,e.candidate_ids);
 insert into private.erasure_purge_manifest
 select target_request,digest,adapter,row_key,private.erasure_hash(row_data) from private.erasure_purge_rows(e.company_id,e.candidate_ids) on conflict do nothing;
 select coalesce(jsonb_object_agg(adapter,n),'{}'::jsonb) into counts from(select adapter,count(*) n from private.erasure_purge_rows(e.company_id,e.candidate_ids) group by adapter)c;
 return jsonb_build_object('manifest_hash',digest,'schema_signature',signature,'counts',counts);
end;$$;

create or replace function private.authorize_retention_suggestion(target_suggestion uuid) returns uuid
language plpgsql volatile security definer set search_path='' set timezone='UTC' set datestyle='ISO, YMD' as $$
declare s private.retention_suggestions;d private.retention_delegations;r private.erasure_subject_resolutions;p jsonb;ticket uuid;result uuid;issued timestamptz;authz jsonb;
begin
 select * into s from private.retention_suggestions where id=target_suggestion for update nowait;
 select * into d from private.retention_delegations where id=s.delegation_id;
 if d.execution_mode<>'automatic' then raise exception using errcode='PT409',message='Automatic delegation required';end if;
 perform private.erasure_execution_gate(false);
 if private.erasure_schema_signature() is distinct from (select schema_signature from private.erasure_inventory_baseline_r12 where singleton) then raise exception using errcode='PT409',message='Unknown schema dependency';end if;
 p:=private.evaluate_retention_subject(s.resolution_id,d.id);
 if p->'blockers'<>'[]'::jsonb or p->>'evidence_hash'<>s.evidence_hash then raise exception using errcode='PT409',message='Retention eligibility changed';end if;
 if exists(select 1 from unnest(s.candidate_ids) x(id) where private.erasure_candidate_frozen(x.id)) then raise exception using errcode='PT409',message='Candidate workflow frozen';end if;
 select * into r from private.erasure_subject_resolutions where id=s.resolution_id;
 -- Fixed graph checks, with unknown schema/JSON/dependencies rejected by the R3 adapter before commit.
 if exists(select 1 from private.contact_requests c where c.company_id=s.company_id and private.erasure_contact_request_candidate(c.company_id,c.operation,c.payload,c.result_id) is null) then raise exception using errcode='PT409',message='Unknown candidate dependency';end if;
 issued:=clock_timestamp();
 insert into private.erasure_preview_tickets(company_id,actor_id,anchor_candidate_id,scope_kind,resolution_id,candidate_ids,manifest_hash,generations,created_at,expires_at)
 values(s.company_id,d.owner_id,r.anchor_candidate_id,'confirmed_subject',r.id,s.candidate_ids,s.evidence_hash,private.erasure_generation_snapshot(s.candidate_ids),issued,issued+interval '5 minutes') returning id into ticket;
 insert into private.erasure_requests(company_id,actor_id,anchor_candidate_id,candidate_ids,scope_kind,preview_ticket_id,manifest_hash,policy_revision,resolution_revision,status,generation)
 values(s.company_id,d.owner_id,r.anchor_candidate_id,s.candidate_ids,'confirmed_subject',ticket,s.evidence_hash,d.policy_revision,r.revision,'authorized',1) returning id into result;
 insert into private.erasure_candidate_lifecycle(candidate_id,company_id,generation,status,request_id)
 select id,s.company_id,1,'frozen',result from unnest(s.candidate_ids) x(id)
 on conflict(candidate_id) do update set generation=erasure_candidate_lifecycle.generation+1,status='frozen',request_id=excluded.request_id;
 authz:=jsonb_build_object('kind','retention_policy','actor_id',d.owner_id,'delegation_id',d.id,'activation_revision',d.revision,'policy_revision',d.policy_revision,'due_generation',s.due_generation,'due_at',s.due_at,'evidence_hash',s.evidence_hash);
 insert into private.retention_authorizations(request_id,authorization_json) values(result,authz);
 update private.retention_suggestions set status='authorized',request_id=result,blockers='[]'::jsonb where id=s.id;
 insert into private.erasure_lifecycle_events(company_id,request_id,actor_id,event,generation) values(s.company_id,result,d.owner_id,'authorized',1);
 -- Reuse the complete reviewed R3 scope validator inside this transaction. This
 -- temporary non-exportable execution never receives a reservation or ledger ACK.
 insert into private.erasure_executions(request_id,company_id,candidate_ids,scope_kind,owner_id,policy_copy,resolution_revision,generation,phase,recovery_retain_until)
 select result,s.company_id,s.candidate_ids,'confirmed_subject',d.owner_id,jsonb_build_object('revision',p2.revision,'rules',p2.rules),r.revision,1,'authorized',clock_timestamp()+interval '1 second'
 from private.candidate_retention_policies p2 where p2.id=d.policy_id;
 perform private.erasure_check_purge_scope(result);
 delete from private.erasure_executions where request_id=result;
 return result;
end;$$;

create or replace function public.get_retention_schedule(target_company uuid) returns jsonb
language plpgsql stable security definer set search_path='' as $$
declare d private.retention_delegations;t private.retention_ticks;c private.erasure_execution_config;p private.candidate_retention_policies;schema_ok boolean;begin
 perform private.erasure_owner(target_company);
 select * into d from private.retention_delegations where company_id=target_company order by revision desc limit 1;
 select * into t from private.retention_ticks where company_id=target_company order by created_at desc,id desc limit 1;
 select * into c from private.erasure_execution_config where singleton;
 select * into p from private.candidate_retention_policies where company_id=target_company order by revision desc limit 1;
 schema_ok:=private.erasure_schema_signature() is not distinct from (select schema_signature from private.erasure_inventory_baseline_r12 where singleton);
 return jsonb_build_object('revision',coalesce(d.revision,0),'delegation_id',d.id,'policy_revision',d.policy_revision,'execution_mode',coalesce(d.execution_mode,'suggest_only'),
 'max_batch',coalesce(d.max_batch,25),'revoked',coalesce(d.revoked,true),'owner_current',d.owner_id is not distinct from auth.uid(),
 'authorization_enabled',coalesce(schema_ok and not d.revoked and d.execution_mode='automatic' and d.owner_id=auth.uid() and d.policy_id=p.id and d.policy_revision=p.revision and p.approved_by=auth.uid()
  and c.enabled and c.external_inventory_verified and c.backup_horizon_days is not null and c.artifact_horizon_days is not null and c.retention_margin_days is not null and not c.restore_isolated,false),
 'production_ready',false,
 'blockers',case when c.enabled and c.external_inventory_verified and c.backup_horizon_days is not null and c.artifact_horizon_days is not null and c.retention_margin_days is not null and not c.restore_isolated then '[]'::jsonb else jsonb_build_array('execution_not_provisioned') end || case when schema_ok then '[]'::jsonb else jsonb_build_array('schema_dependency_unknown') end,
 'oldest_pending_at',(select min(created_at) from (select created_at from private.erasure_executions where company_id=target_company and phase in ('authorized','erasing') union all select r.created_at from private.erasure_requests r where r.company_id=target_company and r.status='authorized' and not exists(select 1 from private.erasure_executions e where e.request_id=r.id)) pending),
 'expired_leases',(select count(*) from private.erasure_executions where company_id=target_company and (pending_phase is not null or (phase='erasing' and not local_purged)) and lease_until<clock_timestamp()),
 'last_tick_at',t.created_at,'lag_seconds',case when t.id is null then null else greatest(0,floor(extract(epoch from statement_timestamp()-t.created_at))) end,
 'suggestions',(select count(*) from private.retention_suggestions where company_id=target_company and status='suggested'),
 'authorized',(select count(*) from private.retention_suggestions where company_id=target_company and status='authorized'),
 'blocked',(select count(*) from private.retention_suggestions where company_id=target_company and status='blocked'),
 'holds',(select count(*) from private.erasure_holds where company_id=target_company and released_at is null));
end;$$;

create function private.erasure_competency_row_guard() returns trigger
language plpgsql security invoker set search_path='' as $$
begin
 if current_user='erasure_purge_owner' then
  if tg_op='DELETE' and private.erasure_purge_allowed(tg_table_schema||'.'||tg_table_name,to_jsonb(old)) then return old;end if;
  raise exception using errcode='42501',message='Purge manifest boundary';
 end if;
 if tg_op='DELETE' then
  if tg_table_name<>'competency_test_drafts' then
   raise exception using errcode='42501',message='Controlled competency erasure required';end if;
  if not exists(select 1 from public.competency_test_attempts a where a.id=(to_jsonb(old)->>'attempt_id')::uuid
   and a.company_id=old.company_id and a.candidate_id=old.candidate_id and a.state='submitted') then
   raise exception using errcode='42501',message='Controlled competency draft deletion required';end if;
 end if;
 perform private.erasure_normal_row_guard(tg_op,tg_table_schema,tg_table_name,
  case when tg_op in ('UPDATE','DELETE') then to_jsonb(old) end,
  case when tg_op<>'DELETE' then to_jsonb(new) end);
 -- Keep the global restore gate locked until commit, including ordinary DELETE.
 perform 1 from private.erasure_execution_config where singleton for share nowait;
 if not found or exists(select 1 from private.erasure_execution_config where singleton and restore_isolated) then
  raise exception using errcode='PT409',message='Competency restore isolation';end if;
 if tg_op='DELETE' then return old;end if;return new;
exception when lock_not_available then raise exception using errcode='PT409',message='Competency retention busy';
end;$$;

